<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('appointments.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$row=null;if($id){$s=db()->prepare('SELECT * FROM appointments WHERE id=?');$s->execute([$id]);$row=$s->fetch();if(!$row){http_response_code(404);exit('Cita no encontrada.');}}
$clients=db()->query('SELECT id,company_name,email,whatsapp FROM clients ORDER BY company_name')->fetchAll();$contacts=db()->query("SELECT id,client_id,CONCAT(first_name,' ',COALESCE(last_name,'')) name,email,whatsapp FROM contacts ORDER BY first_name,last_name")->fetchAll();$deals=db()->query("SELECT id,title FROM deals WHERE status='open' ORDER BY title")->fetchAll();$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle=$row?'Editar cita':'Programar cita';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$title=trim((string)($_POST['title']??''));$client=max(0,(int)($_POST['client_id']??0))?:null;$contact=max(0,(int)($_POST['contact_id']??0))?:null;$deal=max(0,(int)($_POST['deal_id']??0))?:null;$assigned=max(0,(int)($_POST['assigned_to']??0))?:null;$start=str_replace('T',' ',(string)($_POST['start_at']??''));$end=str_replace('T',' ',(string)($_POST['end_at']??''))?:null;$meeting=trim((string)($_POST['meeting_url']??''));$booking=trim((string)($_POST['external_booking_url']??''));$status=(string)($_POST['status']??'scheduled');$notes=trim((string)($_POST['notes']??''));$after=(string)($_POST['after_save']??'stay');
 if($title==='')$errors[]='El título es obligatorio.';if($start==='')$errors[]='La fecha y hora son obligatorias.';if(!in_array($status,['scheduled','completed','cancelled','no_show'],true))$status='scheduled';
 if(!$errors){if($id)db()->prepare('UPDATE appointments SET client_id=?,contact_id=?,deal_id=?,assigned_to=?,title=?,start_at=?,end_at=?,meeting_url=?,external_booking_url=?,status=?,notes=? WHERE id=?')->execute([$client,$contact,$deal,$assigned,$title,$start,$end,$meeting,$booking,$status,$notes,$id]);else{db()->prepare('INSERT INTO appointments(client_id,contact_id,deal_id,assigned_to,title,start_at,end_at,meeting_url,external_booking_url,status,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$client,$contact,$deal,$assigned,$title,$start,$end,$meeting,$booking,$status,$notes,(int)$_SESSION['user_id']]);$id=(int)db()->lastInsertId();}
 if($assigned&&db_table_exists('user_notifications'))create_in_app_notification($assigned,'Nueva reunión asignada',$title.' · '.date('d/m/Y H:i',strtotime($start)),'appointment','appointments.php');log_activity($row?'Cita actualizada':'Cita creada',$client,null,$title);flash('success','Cita guardada.');if(in_array($after,['email','whatsapp'],true))redirect('appointment_send.php?id='.$id.'&channel='.$after);redirect('appointments.php');}}
$v=fn($k,$d='')=>$_POST[$k]??($row[$k]??$d);$dt=fn($k)=>($x=$v($k))?date('Y-m-d\TH:i',strtotime((string)$x)):'';require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2>Datos de la reunión</h2><span class="table-sub">Guarda la cita o envía inmediatamente una invitación al cliente.</span></div><a class="btn btn-light" href="appointments.php">Cancelar</a></div><div class="panel-body form-grid three"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label class="span-2">Título *<input name="title" required value="<?=e($v('title'))?>"></label><label>Estado<select name="status"><?php foreach(['scheduled'=>'Programada','completed'=>'Completada','cancelled'=>'Cancelada','no_show'=>'No asistió']as$k=>$l):?><option value="<?=$k?>" <?=$v('status','scheduled')===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Cliente<select name="client_id"><option value="0">Sin cliente</option><?php foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=(int)$v('client_id',0)===(int)$c['id']?'selected':''?>><?=e($c['company_name'])?></option><?php endforeach;?></select></label><label>Contacto<select name="contact_id"><option value="0">Sin contacto</option><?php foreach($contacts as$c):?><option value="<?=(int)$c['id']?>" data-client="<?=(int)$c['client_id']?>" <?=(int)$v('contact_id',0)===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Negocio<select name="deal_id"><option value="0">Sin negocio</option><?php foreach($deals as$d):?><option value="<?=(int)$d['id']?>" <?=(int)$v('deal_id',0)===(int)$d['id']?'selected':''?>><?=e($d['title'])?></option><?php endforeach;?></select></label><label>Inicio *<input type="datetime-local" name="start_at" required value="<?=e($dt('start_at'))?>"></label><label>Fin<input type="datetime-local" name="end_at" value="<?=e($dt('end_at'))?>"></label><label>Responsable<select name="assigned_to"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=(int)$u['id']?>" <?=(int)$v('assigned_to',(int)$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label class="span-2">Enlace de la reunión<input type="url" name="meeting_url" value="<?=e($v('meeting_url','https://www.socrates.la/meet'))?>"></label><label>Enlace de reserva<input type="url" name="external_booking_url" value="<?=e($v('external_booking_url','https://www.socrates.la/meet'))?>"></label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions appointment-actions"><button class="btn btn-light" name="after_save" value="stay">GUARDAR CITA</button><button class="btn btn-secondary" name="after_save" value="email">GUARDAR Y ENVIAR EMAIL</button><button class="btn btn-success" name="after_save" value="whatsapp">GUARDAR Y ENVIAR WHATSAPP</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
